// claim that came to nothing, and keeping it would go on blocking the order
// it is meant to free. Same reasoning, and the same statement, as
// ReleasePersonalisationLink's transient case.
//
// Guarded on a null message_id as that one is, so a row that did send can
// never be swept away by this however its status was left.
func (q *Queries) ReleaseStalePersonalisationClaims(ctx context.Context) ([]ReleaseStalePersonalisationClaimsRow, error) {
	rows, err := q.db.Query(ctx, releaseStalePersonalisationClaims)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReleaseStalePersonalisationClaimsRow{}
	for rows.Next() {
		var i ReleaseStalePersonalisationClaimsRow
		if err := rows.Scan(&i.OrderID, &i.BrandSlug); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const resetPersonalisationWatermark = `-- name: ResetPersonalisationWatermark :exec
INSERT INTO personalisation_watermarks (brand_slug, watch_from)
VALUES ($1, now())
ON CONFLICT (brand_slug) DO UPDATE SET watch_from = now()
`

// Starts asking from now, ignoring every order placed before.
func (q *Queries) ResetPersonalisationWatermark(ctx context.Context, brandSlug string) error {
	_, err := q.db.Exec(ctx, resetPersonalisationWatermark, brandSlug)
	return err
}

const settlePersonalisationLink = `-- name: SettlePersonalisationLink :one
UPDATE personalisation_links
SET status     = $1::varchar,
    sent_at    = CASE WHEN $1::varchar = 'sent' THEN now() ELSE sent_at END,
    message_id = coalesce($2, message_id),
    detail     = $3,
    template_name = coalesce($4, template_name),
    message_body  = coalesce($5, message_body),
    button_count  = coalesce($6, button_count)
WHERE id = $7
RETURNING id, brand_slug, order_id, token_hash, token_sealed, phone, status, issued_at, expires_at, sent_at, opened_at, confirmed_at, message_id, detail, template_name, message_body, button_count, created_at
`

type SettlePersonalisationLinkParams struct {
	Status       string
	MessageID    *string
	Detail       *string
	TemplateName *string
	MessageBody  *string
	ButtonCount  *int16
	ID           uuid.UUID
}

// Records how the send went.
// CAST, and not decoration. The status argument is used twice - assigned to
// a varchar column and compared with a string literal - and without an
// explicit type Postgres deduces two different ones for the same placeholder
// and refuses the whole statement with "inconsistent types deduced for
// parameter $1". Nothing catches that until it runs: sqlc generates happily,
// the Go compiles, and every settle fails at the database. A link would then
// stay 'pending' forever, which reads as a send that never happened - the job
// is never held, and the floor's copy button finds nothing.
//
// The template and the body are coalesced rather than assigned, so settling a
// refusal cannot blank a message that did go out - and so a caller with
// nothing to freeze passes nothing.
func (q *Queries) SettlePersonalisationLink(ctx context.Context, arg SettlePersonalisationLinkParams) (PersonalisationLink, error) {
	row := q.db.QueryRow(ctx, settlePersonalisationLink,
		arg.Status,
		arg.MessageID,
		arg.Detail,
		arg.TemplateName,
		arg.MessageBody,
		arg.ButtonCount,
		arg.ID,
	)
	var i PersonalisationLink
	err := row.Scan(
		&i.ID,
		&i.BrandSlug,
		&i.OrderID,
		&i.TokenHash,
		&i.TokenSealed,
		&i.Phone,
		&i.Status,
		&i.IssuedAt,
		&i.ExpiresAt,
		&i.SentAt,
		&i.OpenedAt,
		&i.ConfirmedAt,
		&i.MessageID,
		&i.Detail,
		&i.TemplateName,
		&i.MessageBody,
		&i.ButtonCount,
		&i.CreatedAt,
	)
	return i, err
}
